@echo off
title Faust Sovereign Remote Daemon - Console Mode (Foreground)
echo ============================================================
echo   FAUST SOVEREIGN REMOTE DAEMON - CONSOLE MODE
echo   Live Streaming Telegram Logs (Local Disk D:)
echo ============================================================
echo.

set "PYTHON_EXE=D:\Program Files\Python\python.exe"
if not exist "%PYTHON_EXE%" set "PYTHON_EXE=python"

"%PYTHON_EXE%" "D:\My Drive\Blue AI\.agents\scripts\daemon\faust_remote.py" run-foreground

if %ERRORLEVEL% neq 0 (
    echo.
    echo [!] Daemon terminated with error.
    pause
)

@echo off
title Faust Sovereign Remote Daemon - Launcher
echo ========================================================
echo   Launching Faust Sovereign Remote Daemon (Local Disk D:)
echo   Zero-IDE Telegram Mode
echo ========================================================
echo.

set "PYTHON_EXE=D:\Program Files\Python\python.exe"
if not exist "%PYTHON_EXE%" set "PYTHON_EXE=python"

"%PYTHON_EXE%" "D:\My Drive\Blue AI\.agents\scripts\daemon\faust_remote.py" start

if %ERRORLEVEL% neq 0 (
    echo.
    echo [!] An error occurred during startup.
    pause
) else (
    echo.
    timeout /t 3
)

@echo off
title Faust Remote Sovereign Daemon - Launcher
echo ============================================================
echo   LAUNCHING FAUST SOVEREIGN REMOTE DAEMON (ZERO-IDE MODE)
echo ============================================================
echo.

set "PYTHON_EXE=D:\Program Files\Python\python.exe"
if not exist "%PYTHON_EXE%" set "PYTHON_EXE=python"

"%PYTHON_EXE%" "D:\My Drive\Blue AI\.agents\scripts\daemon\faust_remote.py" start

if %ERRORLEVEL% neq 0 (
    echo.
    echo [!] Daemon failed to launch cleanly. Check logs at:
    echo     D:\Program Data\faust_daemon\logs\faust_remote.log
    echo.
    pause
) else (
    echo.
    echo ============================================================
    echo   STATUS: ONLINE (Detached Windows Process Active)
    echo ============================================================
    echo   [+] Telegram link active: @FaustoftheBlueRose_bot
    echo   [+] Topic #4526 (Blue AI) is now listening.
    echo.
    echo   You can safely close this launcher window now.
    echo   Faust will continue running 24/7 in the background
    echo   until you run Stop_Faust_Remote.bat.
    echo ============================================================
    echo.
    pause
)

@echo off
title Faust Sovereign Remote Daemon - Terminator
echo ========================================================
echo   Terminating Faust Sovereign Remote Daemon (Local Disk D:)
echo ========================================================
echo.

set "PYTHON_EXE=D:\Program Files\Python\python.exe"
if not exist "%PYTHON_EXE%" set "PYTHON_EXE=python"

"%PYTHON_EXE%" "D:\My Drive\Blue AI\.agents\scripts\daemon\faust_remote.py" stop

if %ERRORLEVEL% neq 0 (
    echo.
    echo [!] An error occurred during termination.
    pause
) else (
    echo.
    timeout /t 3
)

@echo off
title Faust Remote Sovereign Daemon - Terminator
echo ============================================================
echo   STOPPING FAUST SOVEREIGN REMOTE DAEMON
echo ============================================================
echo.

set "PYTHON_EXE=D:\Program Files\Python\python.exe"
if not exist "%PYTHON_EXE%" set "PYTHON_EXE=python"

"%PYTHON_EXE%" "D:\My Drive\Blue AI\.agents\scripts\daemon\faust_remote.py" stop

if %ERRORLEVEL% neq 0 (
    echo.
    echo [!] An error occurred during daemon shutdown.
    pause
) else (
    echo.
    echo [+] Daemon and all child jobs terminated cleanly.
    timeout /t 3 > nul
)
